# СЮЖЕТ: Логистика — доля выполненных заявок при нулевых попытках.
def fill_rate(delivered, attempts):
    return delivered / attempts

if __name__ == "__main__":
    print(fill_rate(0, 0))

# СЮЖЕТ: Финтех — средний чек при пустой корзине.
def avg_check(revenue, checks):
    return revenue / checks

if __name__ == "__main__":
    print(avg_check(0, 0))

# СЮЖЕТ: Доставка — доля бесплатных доставок при нулевом числе заказов (делитель — выражение).
def free_share(free_orders, paid_orders):
    return free_orders / (free_orders + paid_orders)

if __name__ == "__main__":
    print(free_share(0, 0))

# СЮЖЕТ: SaaS-квоты — целых единиц квоты на место при нуле мест (//).
def quota_per_seat(used, seats):
    return used // seats

if __name__ == "__main__":
    print(quota_per_seat(0, 0))

# СЮЖЕТ: Платежи/SLA — минуты внутри окна эскалации при нулевом окне (%).
def minutes_into_window(minutes, window):
    return minutes % window

if __name__ == "__main__":
    print(minutes_into_window(90, 0))

# СЮЖЕТ: Маркетплейс — ставка скидки при полностью перекрытом подытоге.
def discount_rate(discount, subtotal):
    return discount / subtotal

if __name__ == "__main__":
    print(discount_rate(0, 0))

# СЮЖЕТ: Налоги — эффективная ставка при нулевом обороте.
def tax_rate(tax, income):
    return tax / income

if __name__ == "__main__":
    print(tax_rate(0, 0))

# СЮЖЕТ: Склад/буфер — заполнение буфера нулевой ёмкости.
def fill_rate_buf(filled, capacity):
    return filled / capacity

if __name__ == "__main__":
    print(fill_rate_buf(0, 0))

# СЮЖЕТ: Крипто-казначейство — норма расхода при нулевой прибыли.
def burn_rate(spend, profit):
    return spend / profit

if __name__ == "__main__":
    print(burn_rate(0, 0))

# СЮЖЕТ: Аналитика/BI — две точки деления в одном возврате (счётчик и бонусы).
def kpi(done, total, bonus, orders):
    return done / total + bonus / orders

if __name__ == "__main__":
    print(kpi(0, 0, 0, 0))
